using System;using System.Linq;using System.Collections.Generic;using System.Globalization;
namespace BeamScheduleFormatter {
class BeamNode {public int Id;public double X,Y,Z;}
class BeamMember {public int Id,A,B;}
class BeamDisplacement {public int Node;public string Case;public double X,Y,Z;}
class BeamDeflectionData {public bool ZUp;public readonly Dictionary<int,BeamNode> Nodes=new Dictionary<int,BeamNode>();public readonly Dictionary<int,BeamMember> Members=new Dictionary<int,BeamMember>();public readonly List<BeamDisplacement> Displacements=new List<BeamDisplacement>();}
class PhysicalBeamInput {public string Name,Members,Cases;public int Start,End;public double LimitRatio=360;public string Vertical="Y";public bool ServiceBasis,SupportsVerified;}
class BeamDeflectionStation {public int Node;public double Station,Absolute,Chord,Relative;}
class BeamDeflectionResult {public string Beam,Case,Status;public double Span,LimitMm,MaximumMm,At;public int GoverningNode,StartNode,EndNode;public readonly List<BeamDeflectionStation> Stations=new List<BeamDeflectionStation>();}
static class BeamDeflection {
 internal static double Distance(BeamNode a,BeamNode b){return Math.Sqrt(Math.Pow(a.X-b.X,2)+Math.Pow(a.Y-b.Y,2)+Math.Pow(a.Z-b.Z,2));}
 internal static List<BeamNode> Chain(BeamDeflectionData data,PhysicalBeamInput input){var ids=new HashSet<int>();foreach(string text in (input.Members??"").Split(new[]{',',';',' ','\t'},StringSplitOptions.RemoveEmptyEntries)){int id;if(!int.TryParse(text,out id)||id<=0||!ids.Add(id))throw new Exception("Enter unique positive member IDs for one physical beam.");}if(ids.Count==0)throw new Exception("Enter the members of this physical beam.");var edges=new Dictionary<int,List<int>>();foreach(int id in ids){BeamMember m;if(!data.Members.TryGetValue(id,out m)||!data.Nodes.ContainsKey(m.A)||!data.Nodes.ContainsKey(m.B)||m.A==m.B)throw new Exception("Missing/invalid geometry for member "+id);foreach(var pair in new[]{new[]{m.A,m.B},new[]{m.B,m.A}}){List<int> list;if(!edges.TryGetValue(pair[0],out list)){list=new List<int>();edges.Add(pair[0],list);}list.Add(pair[1]);if(list.Count>2)throw new Exception("Selected members branch; select a single beam path.");}}
 var ends=edges.Where(pair=>pair.Value.Count==1).Select(pair=>pair.Key).ToList();if(ends.Count!=2)throw new Exception("Selected beam must be an open connected chain with two endpoints.");int start=input.Start>0?input.Start:ends.Min();if(!ends.Contains(start))throw new Exception("Start support is not an endpoint of the selected span.");int end=input.End>0?input.End:ends.Single(n=>n!=start);if(!ends.Contains(start)||!ends.Contains(end)||start==end)throw new Exception("Support nodes must be the two endpoints of the selected span. Split the group at real intermediate supports.");var path=new List<BeamNode>();var seen=new HashSet<int>();int current=start,previous=-1;while(true){if(!seen.Add(current))throw new Exception("Loop in beam path.");path.Add(data.Nodes[current]);if(current==end)break;int[] next=edges[current].Where(n=>n!=previous).ToArray();if(next.Length!=1)throw new Exception("Disconnected/ambiguous beam path.");previous=current;current=next[0];}if(path.Count!=ids.Count+1||seen.Count!=edges.Count)throw new Exception("Selected members contain disconnected segments.");if(path.Any(node=>!WindTin.Finite(node.X)||!WindTin.Finite(node.Y)||!WindTin.Finite(node.Z)))throw new Exception("Non-finite node coordinates.");double length=Distance(path[0],path.Last());if(length<=1e-9)throw new Exception("Zero beam span.");double sum=Enumerable.Range(1,path.Count-1).Sum(i=>Distance(path[i-1],path[i]));if(Math.Abs(sum-length)>Math.Max(.001,length*1e-5))throw new Exception("Overlapping or reversed physical beam segments.");foreach(var node in path){double t=((node.X-path[0].X)*(path.Last().X-path[0].X)+(node.Y-path[0].Y)*(path.Last().Y-path[0].Y)+(node.Z-path[0].Z)*(path.Last().Z-path[0].Z))/(length*length);double x=path[0].X+t*(path.Last().X-path[0].X),y=path[0].Y+t*(path.Last().Y-path[0].Y),z=path[0].Z+t*(path.Last().Z-path[0].Z);if(Math.Sqrt(Math.Pow(node.X-x,2)+Math.Pow(node.Y-y,2)+Math.Pow(node.Z-z,2))>Math.Max(.001,length*1e-5))throw new Exception("Selected members are not collinear; this sheet checks a straight physical beam.");}return path;}
 internal static string CaseId(string name){return (name??"").Trim().Split(new[]{':',' '},StringSplitOptions.RemoveEmptyEntries).FirstOrDefault()??"";}
 internal static List<BeamDeflectionResult> Calculate(BeamDeflectionData data,PhysicalBeamInput input){if(!WindTin.Finite(input.LimitRatio)||input.LimitRatio<=0||!new[]{"X","Y","Z"}.Contains(input.Vertical))throw new Exception("Select deflection direction and a positive L/n limit.");var path=Chain(data,input);double span=Distance(path[0],path.Last());double alignment=input.Vertical=="X"?Math.Abs(path.Last().X-path[0].X)/span:input.Vertical=="Y"?Math.Abs(path.Last().Y-path[0].Y)/span:Math.Abs(path.Last().Z-path[0].Z)/span;if(alignment>.999)throw new Exception("Selected displacement component is axial to the beam; choose a transverse/vertical component.");var requested=new HashSet<string>((input.Cases??"").Split(new[]{',',';',' '},StringSplitOptions.RemoveEmptyEntries),StringComparer.OrdinalIgnoreCase);var cases=data.Displacements.Select(d=>d.Case).Distinct(StringComparer.OrdinalIgnoreCase).Where(name=>requested.Count==0||requested.Contains(CaseId(name))).ToList();if(cases.Count==0||requested.Any(name=>!cases.Any(c=>CaseId(c).Equals(name,StringComparison.OrdinalIgnoreCase))))throw new Exception("Selected load case is absent from the displacement data.");var results=new List<BeamDeflectionResult>();foreach(string name in cases){var rows=data.Displacements.Where(d=>d.Case.Equals(name,StringComparison.OrdinalIgnoreCase)).ToList();if(rows.GroupBy(d=>d.Node).Any(g=>g.Count()>1))throw new Exception("Duplicate node displacement in load case "+name);var byNode=rows.ToDictionary(d=>d.Node);if(path.Any(n=>!byNode.ContainsKey(n.Id)))throw new Exception("Load case "+name+" is missing a support/intermediate node displacement.");Func<BeamDisplacement,double> component=d=>input.Vertical=="X"?d.X:input.Vertical=="Y"?d.Y:d.Z;double first=component(byNode[path[0].Id]),last=component(byNode[path.Last().Id]);var result=new BeamDeflectionResult{Beam=input.Name,Case=name,StartNode=path[0].Id,EndNode=path.Last().Id,Span=span,LimitMm=span*1000/input.LimitRatio};foreach(var node in path){double station=Distance(path[0],node),absolute=component(byNode[node.Id]),chord=first+(last-first)*station/span,relative=(absolute-chord)*1000;if(!WindTin.Finite(relative))throw new Exception("Non-finite displacement.");result.Stations.Add(new BeamDeflectionStation{Node=node.Id,Station=station,Absolute=absolute*1000,Chord=chord*1000,Relative=relative});if(Math.Abs(relative)>result.MaximumMm){result.MaximumMm=Math.Abs(relative);result.At=station;result.GoverningNode=node.Id;}}
 result.Status=result.MaximumMm>result.LimitMm?"Sampled deflection EXCEEDS limit":!input.ServiceBasis?"Review load basis; no PASS":!input.SupportsVerified?"Review physical supports; no PASS":"Within limit at imported nodes only; between-node maximum not verified";if(path.Count<3)result.Status="No interior displacement stations: cannot establish beam deflection";results.Add(result);}return results;}
}
}
